insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('0a4bed04-0120-4ef5-bca0-804b56bdcf4a', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', null, 'topic'::public.curated_course_node_type, '1. Elementary Spanish I Review and Novice Expansion', 'The course begins by rebuilding confidence and accuracy from Elementary Spanish I. Students review core present-tense communication while identifying individual gaps before the semester adds past-time narration and more complex sentence patterns.', 0),
  ('dc4ed427-5826-47ab-94d3-96259e0736a8', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '0a4bed04-0120-4ef5-bca0-804b56bdcf4a', 'subtopic'::public.curated_course_node_type, 'Core structures refresh', 'The point is to make first-semester grammar usable again, especially in spontaneous speaking and short writing.', 0),
  ('ecd1178c-7d72-4cb9-b32e-0a646e5c15e4', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'dc4ed427-5826-47ab-94d3-96259e0736a8', 'concept'::public.curated_course_node_type, 'ser, estar, hay, tener, ir', null, 0),
  ('93a80990-b338-4567-8942-f395dcef1eee', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'dc4ed427-5826-47ab-94d3-96259e0736a8', 'concept'::public.curated_course_node_type, 'regular present-tense verbs', null, 1),
  ('9f6b031d-36ce-4ea9-8542-d1465de890f5', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'dc4ed427-5826-47ab-94d3-96259e0736a8', 'concept'::public.curated_course_node_type, 'gustar and preferences', null, 2),
  ('71d98daa-8b51-4cd5-b300-b3b971f97fb3', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'dc4ed427-5826-47ab-94d3-96259e0736a8', 'concept'::public.curated_course_node_type, 'noun-adjective agreement', null, 3),
  ('c3b66432-b544-44dc-985e-79827ea3c6d6', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '0a4bed04-0120-4ef5-bca0-804b56bdcf4a', 'subtopic'::public.curated_course_node_type, 'Questions, negation, and classroom repair', 'Students regain the language needed to ask for information, clarify meaning, and keep conversation moving.', 1),
  ('7c676615-0275-4f3a-9987-ece2bca8cb4b', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'c3b66432-b544-44dc-985e-79827ea3c6d6', 'concept'::public.curated_course_node_type, 'question words', null, 0),
  ('9b0fd782-2c34-48bd-b395-e86a4b027122', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'c3b66432-b544-44dc-985e-79827ea3c6d6', 'concept'::public.curated_course_node_type, 'yes/no questions', null, 1),
  ('784040ed-bc06-476b-a62f-bcfcfa47948c', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'c3b66432-b544-44dc-985e-79827ea3c6d6', 'concept'::public.curated_course_node_type, 'negation', null, 2),
  ('b93c7bb2-5a6c-4878-b60b-ee9a4ad5f0e8', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'c3b66432-b544-44dc-985e-79827ea3c6d6', 'concept'::public.curated_course_node_type, '¿Cómo se dice...? and ¿Qué significa...?', null, 3),
  ('f89ab56f-c445-4074-b8ce-e05e3ddf9095', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '0a4bed04-0120-4ef5-bca0-804b56bdcf4a', 'subtopic'::public.curated_course_node_type, 'Pronunciation and spelling tune-up', 'The goal is to correct persistent sound, stress, accent-mark, and spelling issues before longer speech and writing tasks.', 2),
  ('ca59ce40-4b39-490a-b647-c3ae3bce4ca0', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'f89ab56f-c445-4074-b8ce-e05e3ddf9095', 'concept'::public.curated_course_node_type, 'vowels and syllable stress', null, 0),
  ('89a23bff-3e52-4079-a09a-11daa9b82707', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'f89ab56f-c445-4074-b8ce-e05e3ddf9095', 'concept'::public.curated_course_node_type, 'r/rr and ñ', null, 1),
  ('d388a72f-a1bc-4ac0-8c66-36fb9a34a499', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'f89ab56f-c445-4074-b8ce-e05e3ddf9095', 'concept'::public.curated_course_node_type, 'accent marks', null, 2),
  ('dbb0f12e-bcd2-4862-a44f-80cbeb440d60', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'f89ab56f-c445-4074-b8ce-e05e3ddf9095', 'concept'::public.curated_course_node_type, 'read-aloud self-recording', null, 3),
  ('00e878d5-2e46-4077-bb4b-cc54c90c6892', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', null, 'topic'::public.curated_course_node_type, '2. Stem-Changing and High-Frequency Present-Tense Verbs', 'Stem-changing and irregular present-tense verbs let students talk about wants, abilities, requests, preferences, and daily actions more naturally. This unit expands fluency without abandoning the familiar present-tense frame.', 1),
  ('cc1e2f5a-c0bd-4b03-bde4-a93453362aa6', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '00e878d5-2e46-4077-bb4b-cc54c90c6892', 'subtopic'::public.curated_course_node_type, 'Stem-changing verb patterns', 'Students learn predictable families of changes so forms feel patterned rather than random.', 0),
  ('f4abe215-8d87-49ca-a754-d1c4d1972d6e', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'cc1e2f5a-c0bd-4b03-bde4-a93453362aa6', 'concept'::public.curated_course_node_type, 'e-ie: querer, pensar, empezar', null, 0),
  ('0367c86a-3d4b-4402-971c-8c798dfb860b', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'cc1e2f5a-c0bd-4b03-bde4-a93453362aa6', 'concept'::public.curated_course_node_type, 'o-ue: poder, dormir, volver', null, 1),
  ('c72acebf-0261-4248-9733-3e6c08c83d11', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'cc1e2f5a-c0bd-4b03-bde4-a93453362aa6', 'concept'::public.curated_course_node_type, 'e-i: pedir, servir, repetir', null, 2),
  ('6685aec6-0774-461e-943f-f3cc38e1e9b9', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'cc1e2f5a-c0bd-4b03-bde4-a93453362aa6', 'concept'::public.curated_course_node_type, 'nosotros/as exception patterns', null, 3),
  ('1a283f96-612e-4dfe-90f4-eebf319f1a93', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '00e878d5-2e46-4077-bb4b-cc54c90c6892', 'subtopic'::public.curated_course_node_type, 'Irregular yo forms', 'The point is to control common first-person forms students need in real interaction.', 1),
  ('1ef4c5df-0681-4726-9bb9-1003e1da55f8', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '1a283f96-612e-4dfe-90f4-eebf319f1a93', 'concept'::public.curated_course_node_type, 'hacer/hago', null, 0),
  ('5895ff46-d2b0-4de7-8095-1e2cc86486a2', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '1a283f96-612e-4dfe-90f4-eebf319f1a93', 'concept'::public.curated_course_node_type, 'salir/salgo', null, 1),
  ('8d829733-0e6e-4e7c-93f3-b0f808459737', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '1a283f96-612e-4dfe-90f4-eebf319f1a93', 'concept'::public.curated_course_node_type, 'poner/pongo', null, 2),
  ('8ebcd907-f062-4f7d-ac82-accb179489dc', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '1a283f96-612e-4dfe-90f4-eebf319f1a93', 'concept'::public.curated_course_node_type, 'conocer/conozco and saber/sé', null, 3),
  ('5c683cf1-861f-4fa7-b068-45b6a0cdfbbe', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '00e878d5-2e46-4077-bb4b-cc54c90c6892', 'subtopic'::public.curated_course_node_type, 'Communicative present-tense uses', 'Students practice these verbs in tasks rather than isolated charts.', 2),
  ('d29ba293-dc2e-4fe9-a71c-fc5a742ea5be', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '5c683cf1-861f-4fa7-b068-45b6a0cdfbbe', 'concept'::public.curated_course_node_type, 'requests and needs', null, 0),
  ('6686c880-2e5c-48a0-9eda-619b53cab8c8', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '5c683cf1-861f-4fa7-b068-45b6a0cdfbbe', 'concept'::public.curated_course_node_type, 'plans and preferences', null, 1),
  ('9e6be11b-1029-4370-b3d3-d75d381e753b', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '5c683cf1-861f-4fa7-b068-45b6a0cdfbbe', 'concept'::public.curated_course_node_type, 'daily routines', null, 2),
  ('51e5031e-fbbd-42a8-94ef-6d37bc1d29f1', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '5c683cf1-861f-4fa7-b068-45b6a0cdfbbe', 'concept'::public.curated_course_node_type, 'campus and social life', null, 3),
  ('3735da08-8943-42b3-a2ad-1f134f04e6b8', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', null, 'topic'::public.curated_course_node_type, '3. Reflexive Verbs, Daily Routines, and Reciprocal Actions', 'Reflexive verbs help students describe what people do to or for themselves and each other. The unit connects grammar to routines, wellness, identity, and daily-life comparison.', 2),
  ('745918f4-662c-4593-8747-c5e4e7b52fe8', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '3735da08-8943-42b3-a2ad-1f134f04e6b8', 'subtopic'::public.curated_course_node_type, 'Reflexive meaning and pronouns', 'Students learn when the subject and object refer to the same person and how reflexive pronouns signal that relationship.', 0),
  ('a1d66f2b-2621-4556-92f0-ddaaf8ff8b56', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '745918f4-662c-4593-8747-c5e4e7b52fe8', 'concept'::public.curated_course_node_type, 'me, te, se, nos, os, se', null, 0),
  ('ffab21e3-2f2e-4dd2-be8f-1cc60a102a80', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '745918f4-662c-4593-8747-c5e4e7b52fe8', 'concept'::public.curated_course_node_type, 'levantarse, ducharse, vestirse', null, 1),
  ('31bdf556-b42d-49ad-a42c-d20fad2d5d97', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '745918f4-662c-4593-8747-c5e4e7b52fe8', 'concept'::public.curated_course_node_type, 'pronoun placement', null, 2),
  ('83eaa210-aac4-4e26-9671-75ca47086938', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '745918f4-662c-4593-8747-c5e4e7b52fe8', 'concept'::public.curated_course_node_type, 'non-reflexive vs reflexive contrasts', null, 3),
  ('a33b10a7-4bbf-4859-842a-8b1296be4e1c', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '3735da08-8943-42b3-a2ad-1f134f04e6b8', 'subtopic'::public.curated_course_node_type, 'Daily routines and sequence', 'The gist is to narrate an ordinary day with enough sequence and detail to sound connected.', 1),
  ('9b5741e5-036b-44e7-9222-3352b8c0974a', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'a33b10a7-4bbf-4859-842a-8b1296be4e1c', 'concept'::public.curated_course_node_type, 'por la mañana/tarde/noche', null, 0);
