  ('247b8490-f1c6-47b5-bee2-2e80a6fafa47', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'a33b10a7-4bbf-4859-842a-8b1296be4e1c', 'concept'::public.curated_course_node_type, 'wellness and study habits', null, 3),
  ('e45559bf-98f6-4177-b145-a4ca99f6fde6', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '3735da08-8943-42b3-a2ad-1f134f04e6b8', 'subtopic'::public.curated_course_node_type, 'Reciprocal actions', 'Students learn to describe mutual actions between people, not only individual routines.', 2),
  ('1b023347-18b9-497e-a180-e7c353e6d294', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'e45559bf-98f6-4177-b145-a4ca99f6fde6', 'concept'::public.curated_course_node_type, 'nos vemos', null, 0),
  ('dce1cea5-af50-4103-84ae-08a8cb14272e', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'e45559bf-98f6-4177-b145-a4ca99f6fde6', 'concept'::public.curated_course_node_type, 'se hablan', null, 1),
  ('ffde96a7-288b-45ad-bdb1-f971313faab5', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'e45559bf-98f6-4177-b145-a4ca99f6fde6', 'concept'::public.curated_course_node_type, 'se ayudan', null, 2),
  ('979dbf30-c6d1-4500-879a-ffbdf6ed5592', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'e45559bf-98f6-4177-b145-a4ca99f6fde6', 'concept'::public.curated_course_node_type, 'context for each other vs themselves', null, 3),
  ('c8b07caf-cd11-4f54-876a-c008eb6e4440', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', null, 'topic'::public.curated_course_node_type, '4. Direct and Indirect Object Pronouns', 'Object pronouns make Spanish more natural and less repetitive. Students learn to track people and things across sentences, especially in food, shopping, gift-giving, messages, and advice contexts.', 3),
  ('4b9bff75-fb41-4cdb-ae94-83e2ce464494', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'c8b07caf-cd11-4f54-876a-c008eb6e4440', 'subtopic'::public.curated_course_node_type, 'Direct object pronouns', 'The point is to replace the thing or person directly receiving the action.', 0),
  ('4823ebed-31df-4196-a95e-7213c45273af', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '4b9bff75-fb41-4cdb-ae94-83e2ce464494', 'concept'::public.curated_course_node_type, 'lo, la, los, las', null, 0),
  ('fe56cd46-d7e8-4ae2-ac9f-f45f43279a4b', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '4b9bff75-fb41-4cdb-ae94-83e2ce464494', 'concept'::public.curated_course_node_type, 'person vs thing objects', null, 1),
  ('fd037038-15e6-47f5-9410-2b89fb560bd4', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '4b9bff75-fb41-4cdb-ae94-83e2ce464494', 'concept'::public.curated_course_node_type, 'placement before conjugated verbs', null, 2),
  ('d9fc6f3c-8839-4ad1-8ecf-5987e3d4baee', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '4b9bff75-fb41-4cdb-ae94-83e2ce464494', 'concept'::public.curated_course_node_type, 'placement after infinitives and gerunds', null, 3),
  ('91899b3b-9c86-43cb-9105-54a49ff612be', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'c8b07caf-cd11-4f54-876a-c008eb6e4440', 'subtopic'::public.curated_course_node_type, 'Indirect object pronouns', 'Students learn to mark to whom or for whom an action is done.', 1),
  ('7e91256d-9a9f-4032-bdc7-ec32c00f6a53', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '91899b3b-9c86-43cb-9105-54a49ff612be', 'concept'::public.curated_course_node_type, 'me, te, le, nos, os, les', null, 0),
  ('b65727f0-878d-4ba4-b97b-967672363db8', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '91899b3b-9c86-43cb-9105-54a49ff612be', 'concept'::public.curated_course_node_type, 'dar, decir, escribir, comprar', null, 1),
  ('89aecf06-6060-48bf-bb0c-aeec25156354', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '91899b3b-9c86-43cb-9105-54a49ff612be', 'concept'::public.curated_course_node_type, 'clarifying a + person', null, 2),
  ('dbbc30c4-c9da-4f9f-8d0f-36511eb17a82', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '91899b3b-9c86-43cb-9105-54a49ff612be', 'concept'::public.curated_course_node_type, 'gustar-like review', null, 3),
  ('13d62538-580b-4e17-8e85-771a2b2ba849', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'c8b07caf-cd11-4f54-876a-c008eb6e4440', 'subtopic'::public.curated_course_node_type, 'Double-object pronouns', 'The gist is early recognition and controlled production, not mastery of every nuance.', 2),
  ('e044e04b-0ee3-45aa-9650-bdc19dbf45a3', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '13d62538-580b-4e17-8e85-771a2b2ba849', 'concept'::public.curated_course_node_type, 'se lo / se la patterns', null, 0),
  ('9909f401-3b9f-43a1-a6f4-1daeb4db29f3', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '13d62538-580b-4e17-8e85-771a2b2ba849', 'concept'::public.curated_course_node_type, 'pronoun order', null, 1),
  ('7f31a3d3-c868-47fc-aa8e-d633e9009248', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '13d62538-580b-4e17-8e85-771a2b2ba849', 'concept'::public.curated_course_node_type, 'avoiding le lo', null, 2),
  ('879fbf25-4229-4c98-8e66-d285e5a2fede', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '13d62538-580b-4e17-8e85-771a2b2ba849', 'concept'::public.curated_course_node_type, 'context and clarity', null, 3),
  ('cf9828b5-88ba-4b11-9348-ebd3aaeb2a26', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', null, 'topic'::public.curated_course_node_type, '5. Preterite Tense: Regular, Spelling-Changing, and Irregular Forms', 'The preterite opens the door to storytelling about completed events. Students learn endings, spelling changes, and essential irregulars so they can talk about what happened yesterday, last weekend, or during a trip.', 4),
  ('04b0449b-a653-44a6-94fd-0667bd7b5630', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'cf9828b5-88ba-4b11-9348-ebd3aaeb2a26', 'subtopic'::public.curated_course_node_type, 'Regular preterite forms', 'Students learn the basic completed-action frame for -ar, -er, and -ir verbs.', 0),
  ('9ba49619-09d4-467e-8eb4-522720a9e3a6', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '04b0449b-a653-44a6-94fd-0667bd7b5630', 'concept'::public.curated_course_node_type, '-ar endings', null, 0),
  ('f35e26a3-a5f5-461c-8fd8-84d528171840', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '04b0449b-a653-44a6-94fd-0667bd7b5630', 'concept'::public.curated_course_node_type, '-er/-ir endings', null, 1),
  ('d86d2e13-3342-4001-8fdd-c4e5301f3a40', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '04b0449b-a653-44a6-94fd-0667bd7b5630', 'concept'::public.curated_course_node_type, 'preterite time expressions', null, 2),
  ('14e9990a-1ac3-42df-b1d1-db30a63c1d0c', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '04b0449b-a653-44a6-94fd-0667bd7b5630', 'concept'::public.curated_course_node_type, 'completed event meaning', null, 3),
  ('d97f1679-3a09-439d-a68b-3e91ae105a0e', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'cf9828b5-88ba-4b11-9348-ebd3aaeb2a26', 'subtopic'::public.curated_course_node_type, 'Spelling and stem changes', 'The goal is to preserve pronunciation and recognize predictable changes in particular forms.', 1),
  ('4ebf0e4d-60e6-4658-8e32-1edfbe448546', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'd97f1679-3a09-439d-a68b-3e91ae105a0e', 'concept'::public.curated_course_node_type, 'car/gar/zar yo forms', null, 0),
  ('f6a8c173-b135-4753-9ffe-af08d59b6330', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'd97f1679-3a09-439d-a68b-3e91ae105a0e', 'concept'::public.curated_course_node_type, 'leer, creer, oír', null, 1),
