  ('e3bff9f3-79c1-4dcb-a2d3-06aef181413e', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'd97f1679-3a09-439d-a68b-3e91ae105a0e', 'concept'::public.curated_course_node_type, 'accented endings', null, 3),
  ('0b638a44-ae9c-4834-804a-172f13c0c483', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'cf9828b5-88ba-4b11-9348-ebd3aaeb2a26', 'subtopic'::public.curated_course_node_type, 'High-frequency irregular preterites', 'Students focus on verbs that unlock real narration.', 2),
  ('83708c58-e4ee-4224-b1d4-83f58e673b24', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '0b638a44-ae9c-4834-804a-172f13c0c483', 'concept'::public.curated_course_node_type, 'ir/ser: fui, fuiste...', null, 0),
