insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('c876c923-4ac3-4568-b2f2-07ca011860c9', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', null, 'topic'::public.curated_course_node_type, '6. Past-Time Narration and Preterite/Imperfect Contrast', 'Spanish tells the past through more than one lens. This unit introduces the imperfect and helps students begin choosing between event-focused preterite and background/habit-focused imperfect.', 5),
  ('ed4f6527-5b2d-4cae-8e61-612836354036', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'c876c923-4ac3-4568-b2f2-07ca011860c9', 'subtopic'::public.curated_course_node_type, 'Imperfect forms and core uses', 'Students learn to describe what used to happen, what was happening, and what conditions were like.', 0),
  ('12c4417e-8664-4418-8cd5-dbd4a015375c', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'ed4f6527-5b2d-4cae-8e61-612836354036', 'concept'::public.curated_course_node_type, '-aba and -ía endings', null, 0),
