  ('6a89debc-c886-4e90-b767-f3c44c904388', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'ed4f6527-5b2d-4cae-8e61-612836354036', 'concept'::public.curated_course_node_type, 'feelings, weather, descriptions', null, 3),
  ('f17cb1d9-b797-4a7f-a33d-7789c1d71e29', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'c876c923-4ac3-4568-b2f2-07ca011860c9', 'subtopic'::public.curated_course_node_type, 'Preterite vs imperfect contrast', 'The point is conceptual control: action line versus background, completed event versus habitual setting.', 1),
  ('fe9e60e4-fd26-4637-a078-bc3cf7d0ff55', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'f17cb1d9-b797-4a7f-a33d-7789c1d71e29', 'concept'::public.curated_course_node_type, 'one-time events', null, 0),
  ('e17643b1-111b-4e33-bf5b-0b4cd52e74e9', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'f17cb1d9-b797-4a7f-a33d-7789c1d71e29', 'concept'::public.curated_course_node_type, 'ongoing background', null, 1),
  ('c5b08451-8c30-4dfb-b6e3-6583d5da02a1', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'f17cb1d9-b797-4a7f-a33d-7789c1d71e29', 'concept'::public.curated_course_node_type, 'interruption patterns', null, 2),
  ('ed5abd5c-4566-4186-a5b9-e899d3df6605', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'f17cb1d9-b797-4a7f-a33d-7789c1d71e29', 'concept'::public.curated_course_node_type, 'habitual past with used to', null, 3),
  ('12101d97-b172-4974-b13d-afc0185b28d6', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'c876c923-4ac3-4568-b2f2-07ca011860c9', 'subtopic'::public.curated_course_node_type, 'Connected narration', 'Students practice small stories with sequence, background, and reflection.', 2),
  ('fb2784c0-96a1-477a-8a28-17c7653cc868', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '12101d97-b172-4974-b13d-afc0185b28d6', 'concept'::public.curated_course_node_type, 'timeline words', null, 0),
  ('d2d5eab5-6e31-42c5-b009-47b6a19a508f', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '12101d97-b172-4974-b13d-afc0185b28d6', 'concept'::public.curated_course_node_type, 'setting the scene', null, 1),
  ('62d74b92-301e-4629-acda-9a768e5d61b3', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '12101d97-b172-4974-b13d-afc0185b28d6', 'concept'::public.curated_course_node_type, 'event sequence', null, 2),
  ('a4884f94-c322-4f78-9a13-0edb81890e4c', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '12101d97-b172-4974-b13d-afc0185b28d6', 'concept'::public.curated_course_node_type, 'revision for tense consistency', null, 3),
  ('7c7626d7-7145-4e4e-b295-db3df8368e32', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', null, 'topic'::public.curated_course_node_type, '7. Commands, Requests, and Advice', 'Commands help students move beyond describing into directing, advising, and negotiating. The unit emphasizes practical speech acts: recipes, directions, classroom instructions, travel problems, and polite requests.', 6),
  ('0debf3df-9f5f-40c5-a2fd-3dac44082c53', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '7c7626d7-7145-4e4e-b295-db3df8368e32', 'subtopic'::public.curated_course_node_type, 'Informal and formal commands', 'Students learn how command forms change with audience and relationship.', 0),
  ('1dd53306-6a74-443d-81ac-6241a94f7003', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '0debf3df-9f5f-40c5-a2fd-3dac44082c53', 'concept'::public.curated_course_node_type, 'affirmative tú commands', null, 0),
  ('c14d5f04-ec83-4c13-bfec-95bfe8cf8b80', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '0debf3df-9f5f-40c5-a2fd-3dac44082c53', 'concept'::public.curated_course_node_type, 'negative tú commands', null, 1),
  ('b6258e33-9398-45b7-bfab-b17a20a0c7eb', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '0debf3df-9f5f-40c5-a2fd-3dac44082c53', 'concept'::public.curated_course_node_type, 'usted/ustedes commands', null, 2),
  ('0488d28c-d219-4d3c-ae6a-5f7fef511344', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '0debf3df-9f5f-40c5-a2fd-3dac44082c53', 'concept'::public.curated_course_node_type, 'irregulars: haz, ve, pon, sal, sé', null, 3),
  ('d3eed354-ace9-4c41-9b91-80f470995c39', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '7c7626d7-7145-4e4e-b295-db3df8368e32', 'subtopic'::public.curated_course_node_type, 'Pronoun placement with commands', 'The gist is to attach pronouns to affirmative commands and place them before negative commands.', 1),
  ('be29e828-b796-47a1-a806-9816c6a04ca6', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'd3eed354-ace9-4c41-9b91-80f470995c39', 'concept'::public.curated_course_node_type, 'dímelo', null, 0),
