  ('ac217028-aed7-4848-a3af-44ba8436f9e3', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'd3eed354-ace9-4c41-9b91-80f470995c39', 'concept'::public.curated_course_node_type, 'no lo hagas', null, 2),
  ('5175d926-83eb-4058-b6f9-69bea05d212e', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'd3eed354-ace9-4c41-9b91-80f470995c39', 'concept'::public.curated_course_node_type, 'accent marks with attached pronouns', null, 3),
  ('055999fc-a804-436d-a221-dce9724b1885', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '7c7626d7-7145-4e4e-b295-db3df8368e32', 'subtopic'::public.curated_course_node_type, 'Polite requests and advice', 'Students learn softer ways to ask, recommend, and solve problems.', 2),
  ('eaa6ba14-82bf-4377-a6dd-3053da7f16ef', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '055999fc-a804-436d-a221-dce9724b1885', 'concept'::public.curated_course_node_type, 'por favor and podría', null, 0),
