  ('78438e1d-9630-4507-8dfd-427c3b1a120f', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '055999fc-a804-436d-a221-dce9724b1885', 'concept'::public.curated_course_node_type, 'tener que', null, 2),
  ('9b6f0d75-fed6-4644-964a-8e13d04f9e84', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '055999fc-a804-436d-a221-dce9724b1885', 'concept'::public.curated_course_node_type, 'travel and classroom scenarios', null, 3),
  ('85842f20-bb02-40c4-9964-455babb9791e', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', null, 'topic'::public.curated_course_node_type, '8. Comparisons, Superlatives, and Descriptive Precision', 'Comparisons let students say more than isolated descriptions. They learn to compare people, places, classes, food, routines, and cultural practices with accuracy and nuance.', 7),
  ('76b63ea7-0e4b-42e8-b58c-940a2e6100b7', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '85842f20-bb02-40c4-9964-455babb9791e', 'subtopic'::public.curated_course_node_type, 'Comparisons of inequality', 'Students learn to express more/less than relationships across adjectives, adverbs, nouns, and verbs.', 0),
