  ('42b80545-3652-46a5-acdc-a66257c5c00c', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '76b63ea7-0e4b-42e8-b58c-940a2e6100b7', 'concept'::public.curated_course_node_type, 'quantity comparisons', null, 3),
  ('d196c29f-bc8f-4ccd-beed-6c50df5da1ca', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '85842f20-bb02-40c4-9964-455babb9791e', 'subtopic'::public.curated_course_node_type, 'Comparisons of equality', 'The point is to say two things are similar in quality or amount.', 1),
