  ('a1edb006-6128-4b69-a78f-fa0573c9bf13', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '790cff2d-2df8-44ea-a78c-6553a04cb2fd', 'concept'::public.curated_course_node_type, 'el/la más', null, 0),
