  ('e5d468e8-1eb0-4964-aac8-ceb13edcbd9d', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '790cff2d-2df8-44ea-a78c-6553a04cb2fd', 'concept'::public.curated_course_node_type, 'muy, bastante, demasiado', null, 3),
  ('19f697ec-334f-47fc-bdb0-808072d26853', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', null, 'topic'::public.curated_course_node_type, '9. Food, Health, Shopping, Travel, and Daily-Life Vocabulary', 'This thematic unit turns grammar into practical action. Students use second-semester structures to order, ask prices, describe needs, make plans, handle transportation, and solve common travel or daily-life problems.', 8),
  ('8afcf08a-3769-4657-afe8-cb0b153d30d5', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '19f697ec-334f-47fc-bdb0-808072d26853', 'subtopic'::public.curated_course_node_type, 'Food and restaurant interaction', 'Students learn language for ordering, preferences, dietary needs, and culturally aware dining practices.', 0),
