  ('ca00742f-f74f-4886-8933-47067a387d46', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '19f697ec-334f-47fc-bdb0-808072d26853', 'subtopic'::public.curated_course_node_type, 'Shopping and services', 'The gist is to ask for items, prices, sizes, colors, and help in common service encounters.', 1),
