  ('ba194f59-05f8-40fa-a041-d0c593628048', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', null, 'topic'::public.curated_course_node_type, '10. Cultural Readings, Videos, and Interpretive Strategies', 'Students should encounter Spanish as real communication, not only textbook sentences. This section uses beginner-accessible readings and videos to build comprehension, cultural knowledge, and tolerance for ambiguity.', 9),
  ('1b6b770b-65c7-43df-a2af-18e782113e41', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'ba194f59-05f8-40fa-a041-d0c593628048', 'subtopic'::public.curated_course_node_type, 'Reading strategies', 'Students learn to understand short texts without translating every word.', 0),
  ('0e316306-12ec-4a56-9ba4-6e032e714b44', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '1b6b770b-65c7-43df-a2af-18e782113e41', 'concept'::public.curated_course_node_type, 'titles and visuals', null, 0),
