  ('001c32f4-a0fe-44a0-bcb2-512dadbde7ee', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'ba194f59-05f8-40fa-a041-d0c593628048', 'subtopic'::public.curated_course_node_type, 'Listening and viewing strategies', 'The point is to use repetition, captions, visual context, and prediction to understand spoken Spanish.', 1),
  ('6532b28f-9367-446f-be3d-3a79864804e4', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '001c32f4-a0fe-44a0-bcb2-512dadbde7ee', 'concept'::public.curated_course_node_type, 'first listen for gist', null, 0),
