insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('de7692ed-d56f-4aed-9fdb-f1beb38fc42a', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', null, 'topic'::public.curated_course_node_type, '11. Integrated Oral Presentation and Interpersonal Performance', 'The oral presentation is not a speech pasted onto a grammar course; it is the place where students show they can connect ideas, answer questions, and use the language they have built all year.', 10),
  ('a37d7092-1787-4caf-801a-ad01901f5bf0', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'de7692ed-d56f-4aed-9fdb-f1beb38fc42a', 'subtopic'::public.curated_course_node_type, 'Presentation design', 'Students learn to plan a short talk that is clear, personal, culturally grounded, and within their proficiency level.', 0),
  ('a5b4a998-eab6-446a-9e45-17c7e8b6a47c', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'a37d7092-1787-4caf-801a-ad01901f5bf0', 'concept'::public.curated_course_node_type, 'topic selection', null, 0),
