  ('40775e29-d57c-4226-a5b7-0f9a0fec1ed0', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'c380baa0-3ace-426b-a1ad-19947f8f2cf4', 'concept'::public.curated_course_node_type, 'pronunciation practice', null, 3),
