  ('a10f3aed-c7d7-4f67-b98a-0fc8f3039171', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'be05edb7-e50b-4e65-8b0a-2970728c7c77', 'concept'::public.curated_course_node_type, 'asking follow-up questions', null, 0),
