  ('fde4a5b9-93a7-4914-94b4-8f7a19a6a975', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', 'be05edb7-e50b-4e65-8b0a-2970728c7c77', 'concept'::public.curated_course_node_type, 'peer feedback', null, 3),
  ('912c6a7f-aad6-4240-8496-3b160f6b45c0', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', null, 'topic'::public.curated_course_node_type, '12. Novice-High Portfolio, Writing, and Transition to Intermediate Spanish', 'The final unit gathers evidence of growth and prepares students for Intermediate Spanish I. It makes learning visible through revised writing, oral samples, interpretive work, cultural reflection, and a plan for independent progress.', 11),
