  ('d81d3cb0-f76b-44e7-9822-f692e0f359b8', 'a9b0c1d2-3e4f-4a84-9b44-5c6d7e8f9a14', '64164f2f-7835-4b57-9e50-d50a6f27dc17', 'concept'::public.curated_course_node_type, 'self-correction log', null, 3),
