update public.learning_paths
set
  title = 'Elementary Spanish II',
  goal = 'Elementary Spanish II',
  summary = 'Elementary Spanish II develops novice-high communication, early past narration, cultural interpretation, and readiness for Intermediate Spanish I.',
  data = $esp2json${"slug": "elementary-spanish-ii", "title": "Elementary Spanish II", "description": "Elementary Spanish II develops novice-high communication, early past narration, cultural interpretation, and readiness for Intermediate Spanish I.", "topics": [{"id": "0a4bed04-0120-4ef5-bca0-804b56bdcf4a", "type": "topic", "title": "1. Elementary Spanish I Review and Novice Expansion", "description": "The course begins by rebuilding confidence and accuracy from Elementary Spanish I. Students review core present-tense communication while identifying individual gaps before the semester adds past-time narration and more complex sentence patterns.", "children": [{"id": "dc4ed427-5826-47ab-94d3-96259e0736a8", "type": "subtopic", "title": "Core structures refresh", "children": [{"id": "ecd1178c-7d72-4cb9-b32e-0a646e5c15e4", "type": "concept", "title": "ser, estar, hay, tener, ir"}, {"id": "93a80990-b338-4567-8942-f395dcef1eee", "type": "concept", "title": "regular present-tense verbs"}, {"id": "9f6b031d-36ce-4ea9-8542-d1465de890f5", "type": "concept", "title": "gustar and preferences"}, {"id": "71d98daa-8b51-4cd5-b300-b3b971f97fb3", "type": "concept", "title": "noun-adjective agreement"}], "description": "The point is to make first-semester grammar usable again, especially in spontaneous speaking and short writing."}, {"id": "c3b66432-b544-44dc-985e-79827ea3c6d6", "type": "subtopic", "title": "Questions, negation, and classroom repair", "children": [{"id": "7c676615-0275-4f3a-9987-ece2bca8cb4b", "type": "concept", "title": "question words"}, {"id": "9b0fd782-2c34-48bd-b395-e86a4b027122", "type": "concept", "title": "yes/no questions"}, {"id": "784040ed-bc06-476b-a62f-bcfcfa47948c", "type": "concept", "title": "negation"}, {"id": "b93c7bb2-5a6c-4878-b60b-ee9a4ad5f0e8", "type": "concept", "title": "¿Cómo se dice...? and ¿Qué significa...?"}], "description": "Students regain the language needed to ask for information, clarify meaning, and keep conversation moving."}, {"id": "f89ab56f-c445-4074-b8ce-e05e3ddf9095", "type": "subtopic", "title": "Pronunciation and spelling tune-up", "children": [{"id": "ca59ce40-4b39-490a-b647-c3ae3bce4ca0", "type": "concept", "title": "vowels and syllable stress"}, {"id": "89a23bff-3e52-4079-a09a-11daa9b82707", "type": "concept", "title": "r/rr and ñ"}, {"id": "d388a72f-a1bc-4ac0-8c66-36fb9a34a499", "type": "concept", "title": "accent marks"}, {"id": "dbb0f12e-bcd2-4862-a44f-80cbeb440d60", "type": "concept", "title": "read-aloud self-recording"}], "description": "The goal is to correct persistent sound, stress, accent-mark, and spelling issues before longer speech and writing tasks."}]}, {"id": "00e878d5-2e46-4077-bb4b-cc54c90c6892", "type": "topic", "title": "2. Stem-Changing and High-Frequency Present-Tense Verbs", "description": "Stem-changing and irregular present-tense verbs let students talk about wants, abilities, requests, preferences, and daily actions more naturally. This unit expands fluency without abandoning the familiar present-tense frame.", "children": [{"id": "cc1e2f5a-c0bd-4b03-bde4-a93453362aa6", "type": "subtopic", "title": "Stem-changing verb patterns", "children": [{"id": "f4abe215-8d87-49ca-a754-d1c4d1972d6e", "type": "concept", "title": "e-ie: querer, pensar, empezar"}, {"id": "0367c86a-3d4b-4402-971c-8c798dfb860b", "type": "concept", "title": "o-ue: poder, dormir, volver"}, {"id": "c72acebf-0261-4248-9733-3e6c08c83d11", "type": "concept", "title": "e-i: pedir, servir, repetir"}, {"id": "6685aec6-0774-461e-943f-f3cc38e1e9b9", "type": "concept", "title": "nosotros/as exception patterns"}], "description": "Students learn predictable families of changes so forms feel patterned rather than random."}, {"id": "1a283f96-612e-4dfe-90f4-eebf319f1a93", "type": "subtopic", "title": "Irregular yo forms", "children": [{"id": "1ef4c5df-0681-4726-9bb9-1003e1da55f8", "type": "concept", "title": "hacer/hago"}, {"id": "5895ff46-d2b0-4de7-8095-1e2cc86486a2", "type": "concept", "title": "salir/salgo"}, {"id": "8d829733-0e6e-4e7c-93f3-b0f808459737", "type": "concept", "title": "poner/pongo"}, {"id": "8ebcd907-f062-4f7d-ac82-accb179489dc", "type": "concept", "title": "conocer/conozco and saber/sé"}], "description": "The point is to control common first-person forms students need in real interaction."}, {"id": "5c683cf1-861f-4fa7-b068-45b6a0cdfbbe", "type": "subtopic", "title": "Communicative present-tense uses", "children": [{"id": "d29ba293-dc2e-4fe9-a71c-fc5a742ea5be", "type": "concept", "title": "requests and needs"}, {"id": "6686c880-2e5c-48a0-9eda-619b53cab8c8", "type": "concept", "title": "plans and preferences"}, {"id": "9e6be11b-1029-4370-b3d3-d75d381e753b", "type": "concept", "title": "daily routines"}, {"id": "51e5031e-fbbd-42a8-94ef-6d37bc1d29f1", "type": "concept", "title": "campus and social life"}], "description": "Students practice these verbs in tasks rather than isolated charts."}]}, {"id": "3735da08-8943-42b3-a2ad-1f134f04e6b8", "type": "topic", "title": "3. Reflexive Verbs, Daily Routines, and Reciprocal Actions", "description": "Reflexive verbs help students describe what people do to or for themselves and each other. The unit connects grammar to routines, wellness, identity, and daily-life comparison.", "children": [{"id": "745918f4-662c-4593-8747-c5e4e7b52fe8", "type": "subtopic", "title": "Reflexive meaning and pronouns", "children": [{"id": "a1d66f2b-2621-4556-92f0-ddaaf8ff8b56", "type": "concept", "title": "me, te, se, nos, os, se"}, {"id": "ffab21e3-2f2e-4dd2-be8f-1cc60a102a80", "type": "concept", "title": "levantarse, ducharse, vestirse"}, {"id": "31bdf556-b42d-49ad-a42c-d20fad2d5d97", "type": "concept", "title": "pronoun placement"}, {"id": "83eaa210-aac4-4e26-9671-75ca47086938", "type": "concept", "title": "non-reflexive vs reflexive contrasts"}], "description": "Students learn when the subject and object refer to the same person and how reflexive pronouns signal that relationship."}, {"id": "a33b10a7-4bbf-4859-842a-8b1296be4e1c", "type": "subtopic", "title": "Daily routines and sequence", "children": [{"id": "9b5741e5-036b-44e7-9222-3352b8c0974a", "type": "concept", "title": "por la mañana/tarde/noche"}, {"id": "8521a1ef-a482-435c-a884-f4336aea4e15", "type": "concept", "title": "primero, luego, después"}, {"id": "4e783248-88af-4691-a15a-cc97d1a2c7ad", "type": "concept", "title": "frequency words"}, {"id": "247b8490-f1c6-47b5-bee2-2e80a6fafa47", "type": "concept", "title": "wellness and study habits"}], "description": "The gist is to narrate an ordinary day with enough sequence and detail to sound connected."}, {"id": "e45559bf-98f6-4177-b145-a4ca99f6fde6", "type": "subtopic", "title": "Reciprocal actions", "children": [{"id": "1b023347-18b9-497e-a180-e7c353e6d294", "type": "concept", "title": "nos vemos"}, {"id": "dce1cea5-af50-4103-84ae-08a8cb14272e", "type": "concept", "title": "se hablan"}, {"id": "ffde96a7-288b-45ad-bdb1-f971313faab5", "type": "concept", "title": "se ayudan"}, {"id": "979dbf30-c6d1-4500-879a-ffbdf6ed5592", "type": "concept", "title": "context for each other vs themselves"}], "description": "Students learn to describe mutual actions between people, not only individual routines."}]}, {"id": "c8b07caf-cd11-4f54-876a-c008eb6e4440", "type": "topic", "title": "4. Direct and Indirect Object Pronouns", "description": "Object pronouns make Spanish more natural and less repetitive. Students learn to track people and things across sentences, especially in food, shopping, gift-giving, messages, and advice contexts.", "children": [{"id": "4b9bff75-fb41-4cdb-ae94-83e2ce464494", "type": "subtopic", "title": "Direct object pronouns", "children": [{"id": "4823ebed-31df-4196-a95e-7213c45273af", "type": "concept", "title": "lo, la, los, las"}, {"id": "fe56cd46-d7e8-4ae2-ac9f-f45f43279a4b", "type": "concept", "title": "person vs thing objects"}, {"id": "fd037038-15e6-47f5-9410-2b89fb560bd4", "type": "concept", "title": "placement before conjugated verbs"}, {"id": "d9fc6f3c-8839-4ad1-8ecf-5987e3d4baee", "type": "concept", "title": "placement after infinitives and gerunds"}], "description": "The point is to replace the thing or person directly receiving the action."}, {"id": "91899b3b-9c86-43cb-9105-54a49ff612be", "type": "subtopic", "title": "Indirect object pronouns", "children": [{"id": "7e91256d-9a9f-4032-bdc7-ec32c00f6a53", "type": "concept", "title": "me, te, le, nos, os, les"}, {"id": "b65727f0-878d-4ba4-b97b-967672363db8", "type": "concept", "title": "dar, decir, escribir, comprar"}, {"id": "89aecf06-6060-48bf-bb0c-aeec25156354", "type": "concept", "title": "clarifying a + person"}, {"id": "dbbc30c4-c9da-4f9f-8d0f-36511eb17a82", "type": "concept", "title": "gustar-like review"}], "description": "Students learn to mark to whom or for whom an action is done."}, {"id": "13d62538-580b-4e17-8e85-771a2b2ba849", "type": "subtopic", "title": "Double-object pronouns", "children": [{"id": "e044e04b-0ee3-45aa-9650-bdc19dbf45a3", "type": "concept", "title": "se lo / se la patterns"}, {"id": "9909f401-3b9f-43a1-a6f4-1daeb4db29f3", "type": "concept", "title": "pronoun order"}, {"id": "7f31a3d3-c868-47fc-aa8e-d633e9009248", "type": "concept", "title": "avoiding le lo"}, {"id": "879fbf25-4229-4c98-8e66-d285e5a2fede", "type": "concept", "title": "context and clarity"}], "description": "The gist is early recognition and controlled production, not mastery of every nuance."}]}, {"id": "cf9828b5-88ba-4b11-9348-ebd3aaeb2a26", "type": "topic", "title": "5. Preterite Tense: Regular, Spelling-Changing, and Irregular Forms", "description": "The preterite opens the door to storytelling about completed events. Students learn endings, spelling changes, and essential irregulars so they can talk about what happened yesterday, last weekend, or during a trip.", "children": [{"id": "04b0449b-a653-44a6-94fd-0667bd7b5630", "type": "subtopic", "title": "Regular preterite forms", "children": [{"id": "9ba49619-09d4-467e-8eb4-522720a9e3a6", "type": "concept", "title": "-ar endings"}, {"id": "f35e26a3-a5f5-461c-8fd8-84d528171840", "type": "concept", "title": "-er/-ir endings"}, {"id": "d86d2e13-3342-4001-8fdd-c4e5301f3a40", "type": "concept", "title": "preterite time expressions"}, {"id": "14e9990a-1ac3-42df-b1d1-db30a63c1d0c", "type": "concept", "title": "completed event meaning"}], "description": "Students learn the basic completed-action frame for -ar, -er, and -ir verbs."}, {"id": "d97f1679-3a09-439d-a68b-3e91ae105a0e", "type": "subtopic", "title": "Spelling and stem changes", "children": [{"id": "4ebf0e4d-60e6-4658-8e32-1edfbe448546", "type": "concept", "title": "car/gar/zar yo forms"}, {"id": "f6a8c173-b135-4753-9ffe-af08d59b6330", "type": "concept", "title": "leer, creer, oír"}, {"id": "61256597-f7ab-4c76-a3f7-f052a4256a13", "type": "concept", "title": "-ir stem changes"}, {"id": "e3bff9f3-79c1-4dcb-a2d3-06aef181413e", "type": "concept", "title": "accented endings"}], "description": "The goal is to preserve pronunciation and recognize predictable changes in particular forms."}, {"id": "0b638a44-ae9c-4834-804a-172f13c0c483", "type": "subtopic", "title": "High-frequency irregular preterites", "children": [{"id": "83708c58-e4ee-4224-b1d4-83f58e673b24", "type": "concept", "title": "ir/ser: fui, fuiste..."}, {"id": "c05f3ccc-19f1-4d9b-b9a0-c18b022f125d", "type": "concept", "title": "hacer, tener, estar"}, {"id": "f8e3a78e-5d56-4101-99da-e3fc39f1e6e2", "type": "concept", "title": "poder, poner, venir"}, {"id": "5bc9651c-ada2-4eb0-a065-62b999a87f63", "type": "concept", "title": "decir and traer"}], "description": "Students focus on verbs that unlock real narration."}]}, {"id": "c876c923-4ac3-4568-b2f2-07ca011860c9", "type": "topic", "title": "6. Past-Time Narration and Preterite/Imperfect Contrast", "description": "Spanish tells the past through more than one lens. This unit introduces the imperfect and helps students begin choosing between event-focused preterite and background/habit-focused imperfect.", "children": [{"id": "ed4f6527-5b2d-4cae-8e61-612836354036", "type": "subtopic", "title": "Imperfect forms and core uses", "children": [{"id": "12c4417e-8664-4418-8cd5-dbd4a015375c", "type": "concept", "title": "-aba and -ía endings"}, {"id": "055e37b0-48c8-4d19-bdda-86929a911ac1", "type": "concept", "title": "ser, ir, ver irregulars"}, {"id": "0ecbe0bb-ff08-48c3-9981-e6cecfc20742", "type": "concept", "title": "age and time"}, {"id": "6a89debc-c886-4e90-b767-f3c44c904388", "type": "concept", "title": "feelings, weather, descriptions"}], "description": "Students learn to describe what used to happen, what was happening, and what conditions were like."}, {"id": "f17cb1d9-b797-4a7f-a33d-7789c1d71e29", "type": "subtopic", "title": "Preterite vs imperfect contrast", "children": [{"id": "fe9e60e4-fd26-4637-a078-bc3cf7d0ff55", "type": "concept", "title": "one-time events"}, {"id": "e17643b1-111b-4e33-bf5b-0b4cd52e74e9", "type": "concept", "title": "ongoing background"}, {"id": "c5b08451-8c30-4dfb-b6e3-6583d5da02a1", "type": "concept", "title": "interruption patterns"}, {"id": "ed5abd5c-4566-4186-a5b9-e899d3df6605", "type": "concept", "title": "habitual past with used to"}], "description": "The point is conceptual control: action line versus background, completed event versus habitual setting."}, {"id": "12101d97-b172-4974-b13d-afc0185b28d6", "type": "subtopic", "title": "Connected narration", "children": [{"id": "fb2784c0-96a1-477a-8a28-17c7653cc868", "type": "concept", "title": "timeline words"}, {"id": "d2d5eab5-6e31-42c5-b009-47b6a19a508f", "type": "concept", "title": "setting the scene"}, {"id": "62d74b92-301e-4629-acda-9a768e5d61b3", "type": "concept", "title": "event sequence"}, {"id": "a4884f94-c322-4f78-9a13-0edb81890e4c", "type": "concept", "title": "revision for tense consistency"}], "description": "Students practice small stories with sequence, background, and reflection."}]}, {"id": "7c7626d7-7145-4e4e-b295-db3df8368e32", "type": "topic", "title": "7. Commands, Requests, and Advice", "description": "Commands help students move beyond describing into directing, advising, and negotiating. The unit emphasizes practical speech acts: recipes, directions, classroom instructions, travel problems, and polite requests.", "children": [{"id": "0debf3df-9f5f-40c5-a2fd-3dac44082c53", "type": "subtopic", "title": "Informal and formal commands", "children": [{"id": "1dd53306-6a74-443d-81ac-6241a94f7003", "type": "concept", "title": "affirmative tú commands"}, {"id": "c14d5f04-ec83-4c13-bfec-95bfe8cf8b80", "type": "concept", "title": "negative tú commands"}, {"id": "b6258e33-9398-45b7-bfab-b17a20a0c7eb", "type": "concept", "title": "usted/ustedes commands"}, {"id": "0488d28c-d219-4d3c-ae6a-5f7fef511344", "type": "concept", "title": "irregulars: haz, ve, pon, sal, sé"}], "description": "Students learn how command forms change with audience and relationship."}, {"id": "d3eed354-ace9-4c41-9b91-80f470995c39", "type": "subtopic", "title": "Pronoun placement with commands", "children": [{"id": "be29e828-b796-47a1-a806-9816c6a04ca6", "type": "concept", "title": "dímelo"}, {"id": "23822b84-b69d-45f4-936c-ca5c327960b6", "type": "concept", "title": "cómpralo"}, {"id": "ac217028-aed7-4848-a3af-44ba8436f9e3", "type": "concept", "title": "no lo hagas"}, {"id": "5175d926-83eb-4058-b6f9-69bea05d212e", "type": "concept", "title": "accent marks with attached pronouns"}], "description": "The gist is to attach pronouns to affirmative commands and place them before negative commands."}, {"id": "055999fc-a804-436d-a221-dce9724b1885", "type": "subtopic", "title": "Polite requests and advice", "children": [{"id": "eaa6ba14-82bf-4377-a6dd-3053da7f16ef", "type": "concept", "title": "por favor and podría"}, {"id": "edea4dd0-0917-4080-b78c-10a66f44cf6f", "type": "concept", "title": "deber + infinitive"}, {"id": "78438e1d-9630-4507-8dfd-427c3b1a120f", "type": "concept", "title": "tener que"}, {"id": "9b6f0d75-fed6-4644-964a-8e13d04f9e84", "type": "concept", "title": "travel and classroom scenarios"}], "description": "Students learn softer ways to ask, recommend, and solve problems."}]}, {"id": "85842f20-bb02-40c4-9964-455babb9791e", "type": "topic", "title": "8. Comparisons, Superlatives, and Descriptive Precision", "description": "Comparisons let students say more than isolated descriptions. They learn to compare people, places, classes, food, routines, and cultural practices with accuracy and nuance.", "children": [{"id": "76b63ea7-0e4b-42e8-b58c-940a2e6100b7", "type": "subtopic", "title": "Comparisons of inequality", "children": [{"id": "20e4c4e3-64aa-4b1c-898d-d154ce9eb30a", "type": "concept", "title": "más...que"}, {"id": "37538a75-e5dc-4f94-b263-59c4c1504184", "type": "concept", "title": "menos...que"}, {"id": "2561e656-cf57-4ce6-ba34-f635ba63c3d7", "type": "concept", "title": "irregular comparatives"}, {"id": "42b80545-3652-46a5-acdc-a66257c5c00c", "type": "concept", "title": "quantity comparisons"}], "description": "Students learn to express more/less than relationships across adjectives, adverbs, nouns, and verbs."}, {"id": "d196c29f-bc8f-4ccd-beed-6c50df5da1ca", "type": "subtopic", "title": "Comparisons of equality", "children": [{"id": "7f251557-6a12-42bc-8a3b-c8e4ae64ce4f", "type": "concept", "title": "tan...como"}, {"id": "2517f975-9607-43a6-bc18-570be628e161", "type": "concept", "title": "tanto/a/os/as...como"}, {"id": "fbd0236f-47bd-4ca5-8fa1-3297e8e9a640", "type": "concept", "title": "igual de...que"}, {"id": "d3cc3680-f3bb-4bae-ad52-fb235e1b30e3", "type": "concept", "title": "comparison with verbs"}], "description": "The point is to say two things are similar in quality or amount."}, {"id": "790cff2d-2df8-44ea-a78c-6553a04cb2fd", "type": "subtopic", "title": "Superlatives and intensifiers", "children": [{"id": "a1edb006-6128-4b69-a78f-fa0573c9bf13", "type": "concept", "title": "el/la más"}, {"id": "2c649cd1-a364-4f27-9a65-512433b73703", "type": "concept", "title": "el/la menos"}, {"id": "56f893b9-7cb2-42f4-b794-cf9c5fd7a24e", "type": "concept", "title": "-ísimo/a"}, {"id": "e5d468e8-1eb0-4964-aac8-ceb13edcbd9d", "type": "concept", "title": "muy, bastante, demasiado"}], "description": "Students learn to identify extremes and add emphasis without overusing basic adjectives."}]}, {"id": "19f697ec-334f-47fc-bdb0-808072d26853", "type": "topic", "title": "9. Food, Health, Shopping, Travel, and Daily-Life Vocabulary", "description": "This thematic unit turns grammar into practical action. Students use second-semester structures to order, ask prices, describe needs, make plans, handle transportation, and solve common travel or daily-life problems.", "children": [{"id": "8afcf08a-3769-4657-afe8-cb0b153d30d5", "type": "subtopic", "title": "Food and restaurant interaction", "children": [{"id": "87182629-0905-4ee1-9867-4d93b0f09ecf", "type": "concept", "title": "menus and ingredients"}, {"id": "9151b724-ff75-476b-97f9-bc9fb6ecaa8f", "type": "concept", "title": "ordering politely"}, {"id": "13d1f544-8d27-4fd3-944c-d994bae5f34b", "type": "concept", "title": "meal times"}, {"id": "bd5f29a7-298e-4a2f-b644-0b32c8d4e409", "type": "concept", "title": "regional foods"}], "description": "Students learn language for ordering, preferences, dietary needs, and culturally aware dining practices."}, {"id": "ca00742f-f74f-4886-8933-47067a387d46", "type": "subtopic", "title": "Shopping and services", "children": [{"id": "b31a7ce0-4f7e-4c51-8a15-e17c599b17a5", "type": "concept", "title": "clothing and gifts"}, {"id": "48e22438-3001-4174-83a3-1b8af1735ebf", "type": "concept", "title": "prices and payment"}, {"id": "439de1bc-ac91-49ef-933c-7779800aab54", "type": "concept", "title": "demonstratives"}, {"id": "ae3dff57-9dcf-4e1e-a608-54b76cbd94b6", "type": "concept", "title": "object pronouns in shopping"}], "description": "The gist is to ask for items, prices, sizes, colors, and help in common service encounters."}, {"id": "08a38ad8-3484-4e73-8b58-259000f1dcd3", "type": "subtopic", "title": "Travel, lodging, health, and problem solving", "children": [{"id": "baa747c0-1207-4a2b-aa42-b98a75708111", "type": "concept", "title": "transportation"}, {"id": "b0b8538f-bd22-4e09-b617-d0fce3356560", "type": "concept", "title": "hotel and directions"}, {"id": "6218d263-51b4-4416-8134-fdf340f3151b", "type": "concept", "title": "minor illness and pharmacy"}, {"id": "5d5f9fb1-f6c1-4618-8d55-cf3a406a13db", "type": "concept", "title": "lost items and schedule changes"}], "description": "Students practice common scenarios that require requests, commands, past events, and clarification."}]}, {"id": "ba194f59-05f8-40fa-a041-d0c593628048", "type": "topic", "title": "10. Cultural Readings, Videos, and Interpretive Strategies", "description": "Students should encounter Spanish as real communication, not only textbook sentences. This section uses beginner-accessible readings and videos to build comprehension, cultural knowledge, and tolerance for ambiguity.", "children": [{"id": "1b6b770b-65c7-43df-a2af-18e782113e41", "type": "subtopic", "title": "Reading strategies", "children": [{"id": "0e316306-12ec-4a56-9ba4-6e032e714b44", "type": "concept", "title": "titles and visuals"}, {"id": "67e6ba8c-da83-4ad5-9a9c-9223207a8d2a", "type": "concept", "title": "cognates"}, {"id": "011c1542-0850-43bb-9e90-a08a86d13ef6", "type": "concept", "title": "skimming for gist"}, {"id": "686311b9-15f1-493a-96f7-d7f7adb6269c", "type": "concept", "title": "scanning for details"}], "description": "Students learn to understand short texts without translating every word."}, {"id": "001c32f4-a0fe-44a0-bcb2-512dadbde7ee", "type": "subtopic", "title": "Listening and viewing strategies", "children": [{"id": "6532b28f-9367-446f-be3d-3a79864804e4", "type": "concept", "title": "first listen for gist"}, {"id": "10e4a986-c933-44f6-8b1c-eb9a59f44500", "type": "concept", "title": "second listen for details"}, {"id": "590c45d0-bd5d-4dd3-9b23-4dfb50a83e77", "type": "concept", "title": "caption use"}, {"id": "45a787d6-3c85-445c-a697-96e387faab8b", "type": "concept", "title": "note-taking with key words"}], "description": "The point is to use repetition, captions, visual context, and prediction to understand spoken Spanish."}, {"id": "f9c30cf9-9337-47b5-ab99-e83d584064b1", "type": "subtopic", "title": "Cultural interpretation", "children": [{"id": "ff754117-b4c6-46bd-a7d4-a46655f04d47", "type": "concept", "title": "food and travel practices"}, {"id": "2dc8b055-53da-4e78-b6fe-9647923e162f", "type": "concept", "title": "family and routine differences"}, {"id": "350da597-955b-4941-a759-1f9b13ce8a10", "type": "concept", "title": "media and music"}, {"id": "85c72cfc-2c67-4aea-b5a1-e08c16ce42e2", "type": "concept", "title": "regional variation"}], "description": "Students connect products and practices to perspectives while avoiding stereotypes."}]}, {"id": "de7692ed-d56f-4aed-9fdb-f1beb38fc42a", "type": "topic", "title": "11. Integrated Oral Presentation and Interpersonal Performance", "description": "The oral presentation is not a speech pasted onto a grammar course; it is the place where students show they can connect ideas, answer questions, and use the language they have built all year.", "children": [{"id": "a37d7092-1787-4caf-801a-ad01901f5bf0", "type": "subtopic", "title": "Presentation design", "children": [{"id": "a5b4a998-eab6-446a-9e45-17c7e8b6a47c", "type": "concept", "title": "topic selection"}, {"id": "a395b189-0729-4505-bfdd-9148dc7409f1", "type": "concept", "title": "visual support"}, {"id": "d5c02526-9648-46ea-9bd3-6290336fd726", "type": "concept", "title": "logical sequence"}, {"id": "3108da43-79ae-46fa-94e1-5562defd5073", "type": "concept", "title": "memorized vs practiced speech"}], "description": "Students learn to plan a short talk that is clear, personal, culturally grounded, and within their proficiency level."}, {"id": "c380baa0-3ace-426b-a1ad-19947f8f2cf4", "type": "subtopic", "title": "Connected speech", "children": [{"id": "06438c25-a674-49e2-8fe7-dc5160de1d2d", "type": "concept", "title": "present and past forms"}, {"id": "64b574b8-9f5c-47da-b2c7-2532b719ad00", "type": "concept", "title": "comparisons"}, {"id": "16ac4b12-5d73-4bbc-b41f-aa6b1a9d6a8d", "type": "concept", "title": "transition words"}, {"id": "40775e29-d57c-4226-a5b7-0f9a0fec1ed0", "type": "concept", "title": "pronunciation practice"}], "description": "The goal is novice-high speech: strings of sentences, some connectors, and comprehensible pronunciation."}, {"id": "be05edb7-e50b-4e65-8b0a-2970728c7c77", "type": "subtopic", "title": "Q&A and interpersonal follow-up", "children": [{"id": "a10f3aed-c7d7-4f67-b98a-0fc8f3039171", "type": "concept", "title": "asking follow-up questions"}, {"id": "7cfaaad2-61df-4638-9a35-785dc271af04", "type": "concept", "title": "repair strategies"}, {"id": "4b1d2220-9f65-4ac5-a2c8-2e3e71aecc8d", "type": "concept", "title": "clarifying meaning"}, {"id": "fde4a5b9-93a7-4914-94b4-8f7a19a6a975", "type": "concept", "title": "peer feedback"}], "description": "Students practice responding to real questions rather than only delivering prepared text."}]}, {"id": "912c6a7f-aad6-4240-8496-3b160f6b45c0", "type": "topic", "title": "12. Novice-High Portfolio, Writing, and Transition to Intermediate Spanish", "description": "The final unit gathers evidence of growth and prepares students for Intermediate Spanish I. It makes learning visible through revised writing, oral samples, interpretive work, cultural reflection, and a plan for independent progress.", "children": [{"id": "64164f2f-7835-4b57-9e50-d50a6f27dc17", "type": "subtopic", "title": "Writing portfolio", "children": [{"id": "c207f6bd-4798-4236-928c-3f7f35aa5512", "type": "concept", "title": "routine description"}, {"id": "e3f90733-c088-4433-ba7d-2128507c865d", "type": "concept", "title": "past-event narration"}, {"id": "12ecff20-3f4d-47a0-8a16-9b1e4187d89a", "type": "concept", "title": "cultural response"}, {"id": "d81d3cb0-f76b-44e7-9822-f692e0f359b8", "type": "concept", "title": "self-correction log"}], "description": "Students revise selected work to show accuracy, organization, and growth across the semester."}, {"id": "b51ce85f-0acc-41a0-b4a0-5664074cc714", "type": "subtopic", "title": "Proficiency evidence", "children": [{"id": "9181b091-1701-495a-99c5-dbd82ac27017", "type": "concept", "title": "oral sample"}, {"id": "9e8963a1-481a-411e-b142-b077c19a3e95", "type": "concept", "title": "listening/reading evidence"}, {"id": "dab8fe9f-731d-4ac3-aa38-0ca3503fb796", "type": "concept", "title": "presentation reflection"}, {"id": "8a8d6dd4-f587-4335-a3da-00f1b27f56ec", "type": "concept", "title": "grammar growth notes"}], "description": "The point is to document what students can actually do with Spanish across modes."}, {"id": "c1e6e6d3-0f70-47d6-92f6-d7e196c18c6c", "type": "subtopic", "title": "Transition plan", "children": [{"id": "c476df49-b4ad-4130-814d-a125bbf18c8a", "type": "concept", "title": "spaced retrieval"}, {"id": "06e12f69-c804-4268-bc38-bc8d6df57237", "type": "concept", "title": "graded input"}, {"id": "1d71f63d-98eb-4c9e-8654-09972893ae4f", "type": "concept", "title": "conversation practice"}, {"id": "fc115280-06c9-4b8a-a9ed-84972c512d05", "type": "concept", "title": "goals for Intermediate Spanish I"}], "description": "Students leave with strategies for vocabulary, grammar, input, speaking, and confidence in the intermediate sequence."}]}], "dbBacked": true}$esp2json$::jsonb,
